const $=s=>document.querySelector(s);let files=[],urls=[],example=false,detectedDocument=null,draftTargetLanguage=null;let toastTimer;const typeNames={license:'Führerschein',birth:'Geburtsurkunde',marriage:'Heiratsurkunde',other:'Urkunde'};
function toast(message){(document.querySelector('dialog[open]')||document.body).append($('#toast'));$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',5000)}
function view(name){$('#studio-intro').hidden=name!=='studio';document.querySelectorAll('[data-page-heading]').forEach(el=>el.hidden=el.dataset.pageHeading!==name);for(const n of ['studio','documents','guide','review','workspace']){$(`#${n}-view`).hidden=n!==name;document.querySelector(`[data-view="${n}"]`)?.classList.toggle('active',n===name)}$('#breadcrumb').textContent={studio:'Übersetzen',documents:'Bibliothek',guide:'Hinweise',review:'Bearbeiten',workspace:'Anlernen'}[name];const reviewExtras=$('#review-extras');if(reviewExtras)reviewExtras.hidden=name!=='review';if(name==='documents')renderDocuments();if(name==='workspace'&&typeof loadLibrary==='function')void loadLibrary();window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));for(const id of ['help','workflow-help','sources']){const button=$(`#${id}`);if(button)button.onclick=()=>view('guide');}
$('#pick').onclick=e=>{e.stopPropagation();$('#file').click()};$('#dropzone').onclick=()=>$('#file').click();$('#dropzone').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('#file').click()}};$('#file').onchange=e=>{addFiles(e.target.files);e.target.value=''};
for(const type of ['dragenter','dragover'])$('#dropzone').addEventListener(type,e=>{e.preventDefault();$('#dropzone').classList.add('dragover')});for(const type of ['dragleave','drop'])$('#dropzone').addEventListener(type,e=>{e.preventDefault();$('#dropzone').classList.remove('dragover');if(type==='drop')addFiles(e.dataTransfer.files)});
function resetPreview(){urls.forEach(URL.revokeObjectURL);urls=[];$('#preview').replaceChildren()}
function invalidateDraft(){if(typeof cachedPDF!=='undefined')cachedPDF=null;if(typeof cachedWord!=='undefined')cachedWord=null;example=false;detectedDocument=null;draftTargetLanguage=null;if(typeof convertedPreviews!=='undefined')convertedPreviews.clear();$('#translation').value='';$('#editor').hidden=true;window.hideManualEditor?.();document.querySelectorAll('.review-checks input').forEach(i=>i.checked=false);document.querySelectorAll('.step').forEach(s=>s.classList.toggle('active',s.dataset.step==='1'))}
const fileRoles=new WeakMap(),fileHashes=new WeakMap();let intakeTail=Promise.resolve();
function addFiles(incoming){const captured=[...incoming];intakeTail=intakeTail.then(()=>addUniqueFiles(captured)).catch(e=>{ $('#error').textContent=e.message;});}
async function addUniqueFiles(incoming){if(typeof translating!=='undefined' && translating)return;let errors=[],accepted=[];for(const f of incoming){if(!/\.(pdf|docx|doc|odt|rtf|txt|md|jpe?g|png|webp|gif|tiff?|bmp|heic|heif|avif)$/i.test(f.name)){errors.push(`${f.name}: Dateiformat nicht unterstützt.`);continue}if(!f.size||f.size>20*1024*1024){errors.push(`${f.name}: Datei leer oder größer als 20 MB.`);continue}if(files.length+accepted.length>=10){errors.push('Maximal 10 Dateien pro Sitzung.');break}const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await f.arrayBuffer())),b=>b.toString(16).padStart(2,'0')).join('');if([...files,...accepted].some(x=>fileHashes.get(x)===hash)){errors.push(f.name+': identischer Inhalt bereits ausgewählt.');continue;}fileHashes.set(f,hash);accepted.push(f)}if(accepted.length){invalidateDraft();files.push(...accepted);renderFiles()}$('#error').textContent=errors.join(' ')}
function makeRow(f,i){const row=document.createElement('div');row.className='file-item';const icon=document.createElement('b');icon.textContent=f.name.split('.').pop().toUpperCase().slice(0,5);const name=document.createElement('span');name.textContent=f.name;const size=document.createElement('small');size.textContent=`Datei ${i+1} · ${(f.size/1024/1024).toFixed(2)} MB · lokal ausgewählt`;name.append(size);const remove=document.createElement('button');remove.textContent='×';remove.setAttribute('aria-label',`${f.name} entfernen`);remove.onclick=()=>{files.splice(i,1);invalidateDraft();resetPreview();renderFiles();renderDocuments()};const order=document.createElement('div');order.className='file-order';for(const [symbol,delta,label] of [['↑',-1,'nach oben'],['↓',1,'nach unten']]){const button=document.createElement('button');button.textContent=symbol;button.disabled=i+delta<0||i+delta>=files.length;button.setAttribute('aria-label',`${f.name} ${label}`);button.onclick=()=>{[files[i],files[i+delta]]=[files[i+delta],files[i]];invalidateDraft();resetPreview();renderFiles();renderDocuments();};order.append(button);}const role=document.createElement('select');role.className='file-role';role.setAttribute('aria-label',f.name+' Seitenrolle');for(const [value,label]of [['auto','Automatisch'],['front','Vorderseite'],['back','Rückseite'],['attachment','Beilage']])role.add(new Option(label,value));role.value=fileRoles.get(f)||'auto';role.onchange=()=>{fileRoles.set(f,role.value);invalidateDraft();};row.append(icon,name,role,order,remove);return row}
function renderFiles(){$('#file-list').replaceChildren(...files.map(makeRow));$('#doc-count').textContent=typeof queueState==='undefined'?'0':String(queueState.jobs.length);$('#dropzone h3').textContent=files.length?'Weitere Dateien hinzufügen':'Dateien hier ablegen';$('#upload-tools').hidden=!files.length;if(typeof updateQueueButton==='function')updateQueueButton()}
const libraryFilters={query:'',type:''};
function documentGroup(job){const detected=job.detected?.documentType||'Dokumenttyp noch nicht erkannt';return /führerschein|driving licen[cs]e/i.test(detected)?'Führerscheine':/geburtsurkunde|birth certificate/i.test(detected)?'Geburtsurkunden':/(?:^|\s)pass(?:\s|$)|passport/i.test(detected)?'Pässe':detected;}
function renderDocuments(){
 const target=$('#document-cards'),jobs=typeof queueState!=='undefined'?queueState.jobs||[]:[];
 $('#doc-count').textContent=String(jobs.length);
 if(!target.querySelector('.library-toolbar')){
  const toolbar=document.createElement('div');toolbar.className='library-toolbar';
  const search=document.createElement('input');search.type='search';search.id='library-search';search.placeholder='Dokumente suchen';search.setAttribute('aria-label','Dokumente suchen');search.value=libraryFilters.query;
  const types=document.createElement('select');types.id='library-types';types.setAttribute('aria-label','Dokumenttyp filtern');
  search.oninput=()=>{libraryFilters.query=search.value;renderDocumentRows();};types.onchange=()=>{libraryFilters.type=types.value;renderDocumentRows();};toolbar.append(search,types);
  const host=document.createElement('div');host.id='library-results';host.className='library-results';host.setAttribute('aria-live','polite');target.replaceChildren(toolbar,host);
 }
 const types=$('#library-types'),groups=[...new Set(jobs.map(documentGroup))].sort();const groupSignature=JSON.stringify(groups);if(types.dataset.groups!==groupSignature){types.replaceChildren(new Option('Alle Dokumenttypen',''),...groups.map(group=>new Option(group,group)));types.dataset.groups=groupSignature;}if(!groups.includes(libraryFilters.type))libraryFilters.type='';types.value=libraryFilters.type;
 renderDocumentRows();
}
function renderDocumentRows(){
 const jobs=(typeof queueState!=='undefined'?queueState.jobs:[]).filter(job=>(!libraryFilters.type||documentGroup(job)===libraryFilters.type)&&(!libraryFilters.query||job.names.join(' ').toLocaleLowerCase().includes(libraryFilters.query.toLocaleLowerCase()))).sort((a,b)=>b.createdAt-a.createdAt),host=$('#library-results');if(!host)return;const signature=JSON.stringify([jobs.map(job=>[job.id,job.status,job.hasResult,job.names,job.createdAt,documentGroup(job)]),libraryFilters,document.documentElement.lang]);if(host.dataset.signature===signature)return;host.dataset.signature=signature;
 if(!jobs.length){const empty=document.createElement('div');empty.className='library-empty';const message=document.createElement('p');message.textContent=libraryFilters.query||libraryFilters.type?'Keine passenden Dokumente.':'Noch keine Übersetzungen gespeichert.';const button=document.createElement('button');button.className='secondary';button.textContent='Dokument hinzufügen';button.onclick=()=>view('studio');empty.append(message,button);host.replaceChildren(empty);return;}
 const table=document.createElement('table');table.className='document-table';const head=document.createElement('thead'),heading=document.createElement('tr');for(const title of ['Dokument','Dokumenttyp','Datum','Status','Aktionen']){const cell=document.createElement('th');cell.scope='col';cell.textContent=title;heading.append(cell);}head.append(heading);const body=document.createElement('tbody');
 for(const job of jobs){const row=document.createElement('tr'),name=document.createElement('td'),open=document.createElement('button');open.className='document-open';open.textContent=job.names.join(' · ');open.onclick=()=>{if(job.hasResult)void queueAction('review',job);else if(job.status==='awaiting_answers')void queueAction('answer',job);else setJobsPanel(true);};name.append(open);
  const type=document.createElement('td');type.textContent=documentGroup(job);const date=document.createElement('td');date.className='document-date';date.textContent=job.createdAt?new Intl.DateTimeFormat(document.documentElement.lang==='de'?'de-AT':document.documentElement.lang==='ar'?'ar':'en-GB',{day:'2-digit',month:'2-digit',year:'numeric'}).format(new Date(job.createdAt)):'—';
  const state=queueStatus(job),status=document.createElement('td'),badge=document.createElement('span');badge.className='library-status tone-'+state.tone;badge.textContent=state.label;status.append(badge);
  const actions=document.createElement('td');actions.className='document-actions';if(job.hasResult){for(const [label,action]of [['PDF','download'],['Word','word']]){const button=document.createElement('button');button.className='text-button';button.textContent=label;button.onclick=()=>void queueAction(action,job);actions.append(button);}}
  const more=document.createElement('details');more.className='action-menu';const summary=document.createElement('summary');summary.textContent='•••';summary.setAttribute('aria-label','Weitere Aktionen');const menu=document.createElement('div');menu.className='action-menu-items';for(const [label,action]of (['succeeded','failed','cancelled','expired'].includes(job.status)?[['Löschen','remove']]:[['Abbrechen','cancel']])){const button=document.createElement('button');button.className='text-button';button.textContent=label;button.onclick=()=>{more.open=false;void queueAction(action,job);};menu.append(button);}more.append(summary,menu);actions.append(more);row.append(name,type,date,status,actions);body.append(row);
 }table.append(head,body);host.replaceChildren(table);
}
