function openEditor(){if(!files.length&&!example){$('#error').textContent='Bitte zuerst eine Datei auswählen oder das Beispieldokument öffnen.';$('#dropzone').focus();return}$('#error').textContent='';$('#editor').hidden=false;$('#draft-title').textContent=detectedDocument?`${detectedDocument.documentType} · ${detectedDocument.sourceLanguage} → ${draftTargetLanguage||$('#target-language').value}`:`Automatisch erkennen → ${$('#target-language').value}`;$('#draft-tag').textContent=example?'Fiktive Beispieldaten':'Manueller Entwurf';$('#source-label').textContent=example?'Fiktives Beispiel':'Lokale Datei';resetPreview();if(example){const box=document.createElement('div');box.style.cssText='background:#f5f5f5;border:1px solid #d4d4d4;padding:28px 20px;line-height:2;text-align:center;width:100%;color:#555555';const h=document.createElement('h3');h.textContent='FIKTIVES MUSTER';const ar=document.createElement('p');ar.lang='ar';ar.dir='rtl';ar.textContent='جمهورية مصر العربية\nوزارة الداخلية\nرخصة قيادة\nالاسم: أحمد محمد حسن';ar.style.cssText='white-space:pre-line;font-size:19px;color:#292929;margin:24px 0';const p=document.createElement('p');p.textContent='Nur zur Demonstration der Oberfläche. Kein echtes Ausweisdokument.';box.append(h,ar,p);$('#preview').append(box)}else{const selector=document.createElement('select');selector.setAttribute('aria-label','Datei für Originalvorschau auswählen');files.forEach((f,i)=>selector.add(new Option(f.name,i)));const frame=document.createElement('div');frame.style.width='100%';function display(){frame.replaceChildren();urls.forEach(URL.revokeObjectURL);urls=[];const f=files[+selector.value];if(typeof renderFilePreview==='function'){renderFilePreview(f,frame);return;}const p=document.createElement('p');p.textContent='Originaldatei ausgewählt.';frame.append(p)}selector.onchange=display;$('#preview').append(selector,frame);display()}document.querySelectorAll('.step').forEach(s=>s.classList.toggle('active',Number(s.dataset.step)<=2));window.showManualEditor()}
$('#continue').onclick=()=>{if(!$('#editor').hidden)window.showManualEditor();else openEditor();};$('#target-language').onchange=()=>{if(cachedPDF)cachedPDF=null;if(!$('#editor').hidden){$('#draft-tag').textContent='Zielsprache geändert · erneut übersetzen';}};
