$('#download').onclick=()=>{const text=exportText();if(!text)return;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='translateocr-uebersetzung.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);exported()};$('#print').onclick=()=>{const text=exportText();if(!text)return;$('#print-area').replaceChildren();const h=document.createElement('h1');h.textContent=outputTitle();const p=document.createElement('div');p.textContent=$('#translation').value.trim();$('#print-area').append(h,p);window.print();exported()};window.addEventListener('beforeunload',()=>urls.forEach(URL.revokeObjectURL));
